        test('Simple list - Verify deleting complete list', async () => {
            const rootDir = path.resolve(__dirname, 'project')
            const project = new Project({
                rootDir,
                config: {
                    generatedDir: 'generated2',
                    scope: 'x_abc',
                    scopeId: '11111111111111111111111111111111',
                },
            })
            const output = await project.getOutput()

            expect(output).toHaveLength(4)
            expect(output.find((f) => f.path.endsWith('sys_ui_list_task_null.xml'))).toMatchObject({
                path: path.join(
                    project.getRootDir(),
                    project.getConfig().appOutputDir,
                    'author_elective_update',
                    'sys_ui_list_task_null.xml'
                ),
                content: `<?xml version="1.0"?>
<record_update>
  <sys_ui_list table="task">
    <sys_ui_list action="DELETE">
      <sys_id>538bb66066444d358b86299c5f189e1c</sys_id>
      <sys_scope display_value="x_abc">11111111111111111111111111111111</sys_scope>
      <view name="NULL">Default view</view>
      <name>task</name>
    </sys_ui_list>
  </sys_ui_list>
</record_update>`,
            })
            const keys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
            expect(
                keys.composite.find(
                    ({ table, id }) => table === 'sys_ui_list' && id === '538bb66066444d358b86299c5f189e1c'
                )
            ).toMatchObject({
                deleted: true,
            })
            expect(
                keys.composite.find(
                    ({ table, id }) => table === 'sys_ui_list_element' && id === '6f80c853ea3841bd9bc5c94c74e0cd92'
                )
            ).toMatchObject({
                deleted: true,
            })
            expect(
                keys.composite.find(
                    ({ table, id }) => table === 'sys_ui_list_element' && id === '866e3776cf37439a985a1172ed15f5c0'
                )
            ).toMatchObject({
                deleted: true,
            })
        })

